CREATE TABLE `spell_proc_event__new`( `entry` INTEGER NOT NULL DEFAULT 0, `SchoolMask` INTEGER NOT NULL DEFAULT 0, `SpellFamilyName` INTEGER NOT NULL DEFAULT 0, `SpellFamilyMask0` INTEGER NOT NULL DEFAULT 0, `SpellFamilyMask1` INTEGER NOT NULL DEFAULT 0, `SpellFamilyMask2` INTEGER NOT NULL DEFAULT 0, `procEx` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`entry`));
INSERT INTO `spell_proc_event__new` (`entry`, `SchoolMask`, `SpellFamilyName`, `SpellFamilyMask0`, `SpellFamilyMask1`, `SpellFamilyMask2`, `procEx`) SELECT p.`entry`, p.`SchoolMask`, p.`SpellFamilyName`, CASE WHEN EXISTS (SELECT 1 FROM `dbc_spelleffect` f WHERE f.`SpellID` = p.`entry` AND f.`DifficultyID` = 0 AND f.`EffectIndex` = 0 AND f.`Effect` <> 0 AND f.`EffectAura` IN (107, 108, 109, 112)) THEN p.`SpellFamilyMask0` ELSE 0 END, CASE WHEN EXISTS (SELECT 1 FROM `dbc_spelleffect` f WHERE f.`SpellID` = p.`entry` AND f.`DifficultyID` = 0 AND f.`EffectIndex` = 1 AND f.`Effect` <> 0 AND f.`EffectAura` IN (107, 108, 109, 112)) THEN p.`SpellFamilyMask1` ELSE 0 END, CASE WHEN EXISTS (SELECT 1 FROM `dbc_spelleffect` f WHERE f.`SpellID` = p.`entry` AND f.`DifficultyID` = 0 AND f.`EffectIndex` = 2 AND f.`Effect` <> 0 AND f.`EffectAura` IN (107, 108, 109, 112)) THEN p.`SpellFamilyMask2` ELSE 0 END, p.`procEx` FROM `spell_proc_event` p;
DROP TABLE `spell_proc_event`;
ALTER TABLE `spell_proc_event__new` RENAME TO `spell_proc_event`;
